EXPORT ZZT_VECPAIRS() BEGIN
LOCAL R,E,O:={};
HComplex:=1; A:=0; E:=0; R:=-99;
IFERR R:=stddev([0+1,3],[0+1,3]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
HComplex:=1; A:=0; E:=0; R:=-99;
IFERR R:=stddev([-1,0,1],[2,-3,2]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
HComplex:=1; A:=0; E:=0; R:=-99;
IFERR R:=stddev([0-1,3],[0-1,1]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
HComplex:=1; A:=0; E:=0; R:=-99;
IFERR R:=stddev([0+1,3],[-.5,1.5]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
HComplex:=1; A:=0; E:=0; R:=-99;
IFERR R:=stddev([0+1,2,3],[0+1,1,1]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
HComplex:=1; A:=0; E:=0; R:=-99;
IFERR R:=stddev([ZZT_TICK(1,0),ZZT_TICK(2,2)],[ZZT_TICK(3,1),ZZT_TICK(4,1)]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
RETURN O; END;
ZZT_TICK(D,V) BEGIN A:=A*10+D; RETURN V; END;
ZZT_FAIL(D) BEGIN A:=A*10+D; RETURN 1/0; END;

